create function pg_temp.fail_quote_link() returns trigger language plpgsql as $$
begin
  if new.status = 'converted' then raise exception 'Injected link failure'; end if;
  return new;
end;
$$;
create trigger test_fail_quote_link before update on quotes
for each row execute function pg_temp.fail_quote_link();
set local role authenticated;
set local request.jwt.claim.sub = '91000000-0000-0000-0000-000000000001';
select throws_ok($test$select convert_quote_to_job_with_values(-91001,-91001,'{}')$test$, 'P0001', null, 'link failure aborts transaction');
select is((select count(*) from jobs where quote_id=-91001),0::bigint,'link failure rolls back inserted job');
select ok((select status='accepted' and job_id is null from quotes where id=-91001),'link failure preserves quote state');
reset role;
drop trigger test_fail_quote_link on quotes;
set local role authenticated;
set local request.jwt.claim.sub = '91000000-0000-0000-0000-000000000001';
select lives_ok($test$select convert_quote_to_job_with_values(-91001,-91001,'{"status":"scheduled","work_description":"Edited scope","amount_quoted":250,"scheduled_date":"2026-10-01","notes":"Final notes"}')$test$,'conversion succeeds');
select ok((select q.status='converted' and q.job_id=j.id and j.business_id=q.business_id from quotes q join jobs j on j.quote_id=q.id where q.id=-91001),'bidirectional link saved');
select ok((select status='scheduled' and work_description='Edited scope' and amount_quoted=250 and scheduled_date='2026-10-01'::date and notes='Final notes' from jobs where quote_id=-91001),'edited values retained');
select throws_ok($test$select convert_quote_to_job_with_values(-91001,-91001,'{}')$test$, '23505', null, 'duplicate conversion rejected');
select is((select count(*) from jobs where quote_id=-91001),1::bigint,'only one job exists');
select * from finish();
rollback;
